import json


def to_sft_jsonl(pairs: list[tuple[str, str]], system: str, path: str) -> int:
    count = 0
    with open(path, 'w', encoding='utf-8') as f:
        for question, answer in pairs:
            if not question.strip() or not answer.strip():
                continue
            record = {'messages': [
                {'role': 'system', 'content': system},
                {'role': 'user', 'content': question.strip()},
                {'role': 'assistant', 'content': answer.strip()},
            ]}
            f.write(json.dumps(record, ensure_ascii=False) + '\n')
            count += 1
    return count

from collections import Counter


def cohen_kappa(a: list[str], b: list[str]) -> float:
    if len(a) != len(b) or not a:
        raise ValueError('lists must be non-empty and of equal length')
    n = len(a)
    p_o = sum(x == y for x, y in zip(a, b)) / n
    ca, cb = Counter(a), Counter(b)
    p_e = sum(ca[k] * cb[k] for k in set(ca) | set(cb)) / (n * n)
    if p_e == 1:
        return 1.0
    return (p_o - p_e) / (1 - p_e)

from collections import Counter


def majority_vote(labels: dict[str, list[str]]) -> dict[str, str | None]:
    result = {}
    for item_id, votes in labels.items():
        counts = Counter(votes).most_common()
        if not counts or (len(counts) > 1 and counts[0][1] == counts[1][1]):
            result[item_id] = None
        else:
            result[item_id] = counts[0][0]
    return result

from collections import defaultdict


def make_dpo_pairs(rated: list[dict]) -> list[dict]:
    by_prompt = defaultdict(list)
    for r in rated:
        by_prompt[r['prompt']].append(r)
    pairs = []
    for prompt, items in by_prompt.items():
        best = max(items, key=lambda r: r['score'])
        worst = min(items, key=lambda r: r['score'])
        if best['score'] - worst['score'] >= 1:
            pairs.append({'prompt': prompt, 'chosen': best['response'], 'rejected': worst['response']})
    return pairs
